import * as C from './core.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],e=C.escapeHTML;
let course,state,storage,storeError=null,saveOK=true,sessionMemory=false,route='',tool='tokenizer',position=0,stepped=false,selectedRun='byte-training',tokenText='Hello\nworld',tokenMode='byte',shapeConfig={batch:8,context:64,width:64,heads:4,vocab:257,layers:2},futureToken=9,menu=false,importMessage='',feedback={};
try{storage=window.localStorage;const loaded=C.loadState(storage);state=loaded.state;storeError=loaded.error;if(storeError)sessionMemory=true;}catch{state=C.blankState();sessionMemory=true;storeError='Local saving is unavailable. Export your notes before leaving.';}
function toast(text){$('#toast').textContent=text;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').textContent='',5500);}
function persist(){state.updatedAt=new Date().toISOString();saveOK=!sessionMemory&&C.saveState(storage,state);$$('[data-storage]').forEach(x=>x.textContent=saveOK?'Saved locally':'Save unavailable · export a backup');if(!saveOK&&!storeError){storeError='Local saving is unavailable. Your work remains in this session. Export before closing.';toast(storeError);}return saveOK;}
function heading(title,description,kicker='YOUR WORKSHOP'){return `<div class="page-title"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1>${description?`<p class="muted">${description}</p>`:''}</div></div>`;}
function link(to,title,icon,current=false){return `<a class="nav-link" href="#/${to}" ${current?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span>${title}</a>`;}
function badges(id){const p=state.lessons[id]||{};return `<span class="status-text">${p.checked?'Understanding checked':p.practiced?'Practiced':p.read?'Read':p.reading?'Reading':'Not started'}</span>`;}
function home(){const id=C.nextLesson(state),m=course.modules.find(m=>m.id===id),read=Object.values(state.lessons).filter(p=>p.read).length,practiced=Object.values(state.lessons).filter(p=>p.practiced).length,checked=Object.values(state.lessons).filter(p=>p.checked).length;return heading(state.lastLesson?'Welcome back to your workshop.':'Learn a little. Build understanding.','Follow one small language model from its first token to an experiment you can explain.',state.lastLesson?'PICK UP WHERE YOU LEFT OFF':'A CLEAR PLACE TO BEGIN')+`<section class="panel next-lesson" aria-labelledby="next-title"><div class="next-copy"><span class="tag">${state.lastLesson?'YOUR NEXT STEP':'YOUR FIRST SITTING'}</span><h2 id="next-title">${e(m.title)}</h2><p class="muted">${e(m.outcome)}. ${id==='00'?'Begin by separating the browser, your Python environment, and saved model weights.':'Read the explanation, try the exercise, and leave a note at the stopping point.'}</p><div class="row"><a class="button primary" href="#/lesson/${id}">${state.lastLesson?'Continue learning':'Start learning'} →</a><span class="meta">Lesson ${id} · ${id==='12'?'2–3 sittings':m.suggested_minutes+' minutes'}</span></div></div><div class="flow-preview"><p class="eyebrow">One experiment, made visible</p><div class="flow-step"><code>Text → IDs</code><span>Choose a representation</span></div><div class="flow-line"></div><div class="flow-step"><code>Model → loss</code><span>Predict, measure, update</span></div><div class="flow-line"></div><div class="flow-step"><code>Evidence</code><span>Validate, save, explain</span></div></div></section><div class="section-head"><h2>Your learning, at your pace</h2><a class="quiet-link" href="#/roadmap">View all 13 lessons ↗</a></div><div class="two-col"><section class="panel"><div class="row between"><h3>Reading progress</h3><span class="small">${read} / 13 lessons</span></div><div class="progress-track" role="progressbar" aria-label="Lessons read" aria-valuemin="0" aria-valuemax="13" aria-valuenow="${read}"><span style="width:${read/13*100}%"></span></div><p class="small muted">${practiced} practiced · ${checked} understanding checked</p><p class="small muted">Review any lesson freely. Reading progress does not award capstone evidence.</p></section><section class="panel"><h3>A good stopping point matters</h3><p class="muted">Most lessons fit into 15–25 minutes. Save one observation, then come back when you’re ready.</p><a class="quiet-link" href="#/notebook">Open your experiment notebook →</a></section></div><section><div class="section-head"><h2>Keep the ideas close to the evidence</h2></div><a class="resource-row" href="#/explore/tokenizer"><span><strong>Explore one operation</strong><small>Text, tokens, shifted targets, attention, and model shapes</small></span><span class="arrow">↗</span></a><a class="resource-row" href="#/results"><span><strong>Read a real, modest result</strong><small>200 recorded CPU updates. Better loss, still repetitive text.</small></span><span class="arrow">↗</span></a></section><div class="callout"><strong>The browser is your guide.</strong> Training runs in the supplied Python labs on your computer. Browser explorations and imported results do not run Python.</div>`;}
function roadmap(){return heading('Your path through the course.','Thirteen lessons, one connected experiment. Start anywhere when you’re reviewing.','COURSE ROADMAP')+`<div class="roadmap">${course.modules.map(m=>`<a href="#/lesson/${m.id}" class="roadmap-row"><span class="road-number">${m.id}</span><div><h2>${e(m.title)}</h2><p>${e(m.outcome)}</p><span class="small muted">${m.id==='12'?'Two or three sittings':m.suggested_minutes+' minute first sitting'} · Lab ${m.lab}</span></div><div>${badges(m.id)} →</div></a>`).join('')}</div>`;}
const questions=[
['Windows has PyTorch, but WSL reports “No module named torch.” What should you check first?',['The Python environment and interpreter path','The model’s attention weights','The number of training updates'],0,'Windows and WSL use separate Python environments. No model has run yet. Record sys.executable and select the intended environment.'],
['For [4, 6, 2, 9, 3], which target follows input [4, 6, 2, 9]?',['[4, 6, 2, 9]','[6, 2, 9, 3]','[2, 9, 3, 4]'],1,'Shift once: targets are [6, 2, 9, 3]. The second prediction sees [4, 6] and predicts 2.'],
['Two tokenizers have 320 entries. Can their model weights necessarily be exchanged?',['Yes, their shapes match','Only if generation is greedy','No, ID-to-piece mappings can differ'],2,'Matching vocabulary sizes do not establish the same ID mapping. Model weights depend on the exact saved tokenizer.'],
['What is the stronger way to divide a collection of stories?',['Split related documents before making windows','Randomly mix overlapping windows','Reuse training data for validation'],0,'Split documents or related groups first. Exact duplicate checks still cannot rule out near duplicates or shared templates.'],
['Vocabulary grows from 257 to 320; width stays 64. What changes?',['Intermediate vectors become width 320','Input table and output projection grow; width stays 64','Only the position embedding'],1,'Both separate vocabulary matrices gain 63 × 64 parameters: 8,064 in total. Intermediate representations keep width 64.'],
['Changing the last input token should do what to earlier-position scores in evaluation mode?',['Change all earlier scores','Leave earlier scores unchanged','Remove the causal mask'],1,'Earlier positions cannot attend to future tokens. The diagram illustrates the rule; the Python regression test checks model behavior.'],
['Which configuration is valid?',['Width 64, heads 6','Width 64, heads 4','Width 64, heads 3'],1,'Width must divide evenly by heads. Four heads each get 16 coordinates.'],
['If you generate text ten times, how many optimizer updates did that add?',['Ten','One','Zero'],2,'Generation uses saved weights without updating them. Resume continues training; train starts fresh.'],
['Low validation loss on story templates establishes what?',['Reliable answers to science questions','Better prediction on those sampled validation windows','A generally capable chatbot'],1,'Evidence is limited to the synthetic distribution and sampled-window protocol. It does not demonstrate unrelated capabilities.'],
['After Ctrl+C between saved checkpoints, resume starts at which step?',['The last number printed in the terminal','The step stored in the checkpoint','Always step zero'],1,'Updates since the last saved evaluation boundary were not retained. Inspect the checkpoint.'],
['Width, steps, and data all change, and the sample improves. What can you conclude?',['The width caused improvement','More steps caused improvement','This comparison cannot isolate one cause'],2,'Keep the observation, but change one factor or plan an experiment that separates effects before claiming a cause.'],
['What distinguishes training LoRA adapters from a fresh TinyLM run?',['Starting weights and which parameters are trained','Both start from random base weights','Neither uses optimization'],0,'LoRA adapts an existing model through small trainable matrices while selected base weights stay frozen. TinyLM starts with random weights.']];
function knowledgeCheck(id){if(id==='12')return `<section class="panel"><h2>Make the evidence inspectable</h2><p>Reading does not verify a training run. Record artifact references and unresolved items.</p><a class="button primary" href="#/capstone">Open capstone evidence →</a></section>`;const q=questions[+id];return `<section id="knowledge-check" class="panel exercise"><p class="eyebrow">PREDICT · THEN CHECK</p><h2>Try one small check</h2><form id="quiz-form" data-lesson="${id}"><fieldset><legend>${e(q[0])}</legend>${q[1].map((label,i)=>`<label class="choice"><input type="radio" name="answer" value="${i}" required ${feedback[id]?.selection===i?'checked':''}><span>${e(label)}</span></label>`).join('')}</fieldset><button class="primary" type="submit">Check my answer</button><div id="quiz-feedback" class="feedback" role="status" aria-live="polite">${feedback[id]?`${feedback[id].correct?'<strong>That’s right.</strong>':'<strong>Try the idea again.</strong>'} ${e(q[3])}`:''}</div></form><p class="small muted">This checks one idea. It does not verify that you ran the Python lab.</p></section>`;}
function lesson(id){const m=course.modules.find(m=>m.id===id);if(!m)return missing();C.visitLesson(state,id);persist();const related={'01':'prediction','02':'tokenizer','04':'shapes','05':'attention','06':'shapes'};return `<div class="row between lesson-top"><a href="#/roadmap" class="quiet-link">← Course roadmap</a><span class="meta">Lesson ${id} of 00–12 · ${id==='12'?'2–3 sittings':m.suggested_minutes+' min'} · Lab ${m.lab}</span></div>`+heading(e(m.title),e(m.outcome),'LESSON '+id)+`<div class="reader-grid"><article class="lesson-body"><div class="session-path" aria-label="Lesson rhythm"><span>01 Explain</span><span>02 Work an example</span><span>03 Try & check</span><span>04 Pause</span></div>${related[id]?`<div class="explore-callout"><div><strong>Make the idea visible</strong><p class="small muted">Explore this operation, then return to the lesson.</p></div><a class="button" href="#/explore/${related[id]}?from=${id}">Open interactive view ↗</a></div>`:''}${['07','08'].includes(id)?'<div class="explore-callout"><span>Connect this lesson to the measured example.</span><a class="button" href="#/results">Open recorded results ↗</a></div>':''}${id==='09'?'<a class="button" href="#/checkpoints">Explore the checkpoint journey ↗</a>':''}<div class="prose">${C.markdown(course.lessons[id],m.path,{omitTitle:true,os:state.os})}</div>${knowledgeCheck(id)}<section class="panel pause-panel"><p class="eyebrow">A PLACE TO PAUSE</p><h2>Keep one useful observation.</h2><label for="lesson-note">What will you want to remember next time?</label><textarea id="lesson-note" rows="3" data-quick-note placeholder="Add an observation to your notebook…"></textarea><div class="row"><button data-action="save-quick" data-id="${id}">Add to notebook</button><a href="#/notebook" class="quiet-link">Open notebook</a></div><fieldset class="progress-choices"><legend>Your own progress</legend><label><input data-progress="read" data-id="${id}" type="checkbox" ${state.lessons[id]?.read?'checked':''}> I’ve read this lesson</label><label><input data-progress="practiced" data-id="${id}" type="checkbox" ${state.lessons[id]?.practiced?'checked':''}> I’ve tried the exercise</label><p class="small muted">Understanding check: <span data-check-state>${state.lessons[id]?.checked?'answered correctly':'not yet checked'}</span>. Separate from capstone evidence.</p></fieldset><nav class="row between" aria-label="Previous and next lesson">${+id>0?`<a class="button" href="#/lesson/${String(+id-1).padStart(2,'0')}">← Previous</a>`:'<a class="button" href="#/">Back home</a>'}${+id<12?`<a class="button primary" href="#/lesson/${String(+id+1).padStart(2,'0')}">Next lesson →</a>`:'<a class="button primary" href="#/capstone">Gather your evidence →</a>'}</nav></section></article><aside class="reader-rail"><p class="eyebrow">THIS SITTING</p><button data-action="scroll-section" data-target="section-0">Read the explanation</button><button data-action="scroll-section" data-target="${id==='12'?'section-1':'knowledge-check'}">Try the check</button><a href="#/labs">Lab ${m.lab} · local commands</a><a href="#/glossary">Keep the glossary close</a><hr class="divider"><label for="command-os">Command environment</label><select id="command-os" data-os><option value="wsl" ${state.os==='wsl'?'selected':''}>WSL / Linux</option><option value="windows" ${state.os==='windows'?'selected':''}>Windows PowerShell</option></select><p class="small muted">Working folder:<br><code>llm-foundations-v2/</code><br>Copying a command does not execute it.</p><a href="course/${m.path}" download>Download lesson source</a></aside></div>`;}
function key(){return `<details class="visual-key"><summary>How to read these diagrams</summary><div class="key-items"><span class="key-text">Text · characters</span><span class="key-token">Token IDs · addresses</span><span class="key-vector">Vectors · coordinates</span><span class="key-weight">Weights · learned numbers</span><span class="key-target">Targets · correct next IDs</span><span class="key-result">Results · measurements</span></div><p class="small muted">Labels carry the meaning; color is a second cue.</p></details>`;}
function explorer(which,from){tool=['tokenizer','prediction','attention','shapes'].includes(which)?which:'tokenizer';return heading('See the operation.','Change one thing, follow what moves, and connect it back to the lesson.','INTERACTIVE WORKSHOP')+`${from?`<a class="quiet-link" href="#/lesson/${e(from)}">← Return to lesson ${e(from)}</a>`:''}<nav class="tool-nav" aria-label="Interactive views">${[['tokenizer','Tokenization'],['prediction','Shifted targets'],['attention','Causal attention'],['shapes','Model shapes']].map(([id,name])=>`<a href="#/explore/${id}${from?'?from='+e(from):''}" ${tool===id?'aria-current="page"':''}>${name}</a>`).join('')}</nav>${key()}<div id="explorer-panel">${tool==='tokenizer'?tokenizerView():tool==='shapes'?shapesView():predictionView(tool==='attention')}</div>`;}
function tokenizerView(){return `<section class="panel"><div class="row between"><h2>Text in. The same text out.</h2><span class="tag">Actual encoding · no model training</span></div><p class="muted">Byte mode uses UTF-8. Teaching BPE applies the supplied saved merge rules in order. Neither updates model weights.</p><div class="two-col controls"><div><label for="tokenizer-mode">Tokenizer</label><select id="tokenizer-mode"><option value="byte" ${tokenMode==='byte'?'selected':''}>Built-in byte · 257 entries</option><option value="bpe" ${tokenMode==='bpe'?'selected':''}>Supplied teaching BPE · 320 entries</option></select></div><div><label for="token-example">Try a reference example</label><select id="token-example"><option value="">Your own text</option><option value="0">A real newline</option><option value="1">Spaces and a tab</option><option value="2">Accent, emoji, and Chinese</option></select></div></div><label for="token-text">Input text · whitespace is data</label><textarea id="token-text" rows="3" maxlength="1500" spellcheck="false">${e(tokenText)}</textarea><div id="token-result" aria-live="polite">${tokenizerResult()}</div></section>`;}
function tokenizerResult(){const t=course.runs[tokenMode==='byte'?'byte-training':'bpe-check'].manifest.tokenizer,r=C.tokenize(tokenText,t);return `<div class="token-stage"><div class="row between"><h3><span class="stage-number">01</span> UTF-8 bytes</h3><span class="meta">${r.bytes.length} bytes</span></div><div class="byte-line">${r.bytes.length?r.bytes.join(' · '):'No bytes yet. Enter some text.'}</div></div><div class="token-stage"><div class="row between"><h3><span class="stage-number">02</span> Token IDs</h3><span class="meta">${r.ids.length} tokens · EOS is not added here</span></div><div class="tokens">${r.ids.map(id=>`<span class="token"><span class="piece">${e(C.visiblePiece(r.pieces[id]))}</span><b>${id}</b><span class="sr-only"> bytes ${r.pieces[id].join(', ')}</span></span>`).join('')||'<p class="muted">Token IDs will appear here.</p>'}</div><p class="small muted">␠ space · ↵ newline · ⇥ tab. Hex bytes show a token that contains only part of a Unicode character.</p></div><div class="token-stage"><h3><span class="stage-number">03</span> Reconstructed text</h3><pre class="reconstructed">${e(r.decoded)||' '}</pre><p class="round-trip"><strong>${r.roundTrip?'✓ Exact round trip':'Round trip failed'}</strong> · ${r.roundTrip?'Decoded text matches, including whitespace.':'Check the representation first.'}</p></div><details><summary>${tokenMode==='byte'?'Why there are no merges':'Inspect saved rules and applied merges'}</summary>${tokenMode==='byte'?'<p>The byte tokenizer is fixed. IDs 0–255 map to bytes; 256 is EOS.</p>':`<p>These 63 rules were learned from training documents, before model weight updates. The browser applies them; it does not retrain the tokenizer.</p><p>${r.trace.length} rules matched this input.</p><div class="table-wrap" tabindex="0" role="region" aria-label="Saved merge rules"><table><thead><tr><th scope="col">New ID</th><th scope="col">Earlier pair</th><th scope="col">Piece</th><th scope="col">Matches</th></tr></thead><tbody>${t.merges.map(([l,rid],i)=>`<tr><th scope="row">${257+i}</th><td>${l} + ${rid}</td><td><code>${e(C.visiblePiece(r.pieces[257+i]))}</code></td><td>${r.trace.find(x=>x.id===257+i)?.count??0}</td></tr>`).join('')}</tbody></table></div>`}</details>`;}
function predictionView(attention=false){const seq=[4,6,2,futureToken,3],r=C.prediction(seq,position);return `<section class="panel"><div class="row between"><h2>${attention?'Who can see which position?':'The next token becomes the target.'}</h2><span class="tag simulation">Simulation · ${stepped?'stepped; paused':'paused'}</span></div><p class="muted">A structural illustration using token IDs, not computed model predictions or attention weights.</p><div class="prediction-grid"><div class="alignment"><div class="sequence-row"><span>Input</span>${r.inputs.map((n,i)=>`<button data-position="${i}" aria-pressed="${i===position}" aria-label="Inspect prediction at position ${i}" class="sequence-token ${i<=position?'available':''}">${n}<small>position ${i}</small></button>`).join('')}</div><div class="sequence-row targets"><span>Target</span>${r.targets.map((n,i)=>`<span class="sequence-token ${i===position?'selected-target':''}">${n}<small>next ID</small></span>`).join('')}</div></div><div class="mask-wrap"><table class="mask"><caption>Causal mask · rows read columns</caption><thead><tr><th scope="col">Query</th>${r.inputs.map((_,i)=>`<th scope="col">${i}</th>`).join('')}</tr></thead><tbody>${r.inputs.map((_,i)=>`<tr class="${i===position?'selected-row':''}"><th scope="row">${i}</th>${r.inputs.map((_,j)=>`<td class="${j<=i?'allowed':'blocked'}"><span aria-hidden="true">${j<=i?'✓':'×'}</span><span class="sr-only">${j<=i?'Allowed':'Hidden'}</span></td>`).join('')}</tr>`).join('')}</tbody></table></div></div><div class="callout" role="status">Position <strong>${position}</strong> can use <strong>[${r.allowed.join(', ')}]</strong> to predict target <strong>${r.target}</strong>. ${position<3?'Later input positions are hidden. Reading the next position would reveal the answer.':'All four inputs are available; the target comes next.'}</div><div class="row"><button data-action="step-back" ${position===0?'disabled':''}>← Previous position</button><button class="primary" data-action="step" ${position===3?'disabled':''}>Step forward →</button><button data-action="reset-simulation">Reset</button></div><div class="future-edit"><label for="future-token">Change the last input ID (position 3)</label><input type="number" id="future-token" min="0" max="999" value="${futureToken}"><p class="small muted">At positions 0 and 1, allowed context and target stay the same. The future ID remains hidden. Python tests, not this diagram, verify unchanged earlier model scores.</p></div></section>`;}
function shapesView(){let r,error;try{r=C.shapes(shapeConfig);}catch(ex){error=ex.message;}return `<section class="panel"><div class="row between"><h2>Follow the shape of one batch.</h2><span class="tag simulation">Shape calculator · no model execution</span></div><p class="muted">Change the recipe. See where each setting matters in the supplied TinyLM.</p><div class="shape-controls">${[['batch','Batch',[1,2,8]],['context','Context',[16,32,64]],['width','Width',[32,64,128]],['heads','Heads',[2,4,6,8]],['vocab','Vocabulary',[257,320]],['layers','Layers',[1,2,4]]].map(([name,label,values])=>`<div><label for="shape-${name}">${label}</label><select id="shape-${name}" data-shape="${name}">${values.map(v=>`<option ${shapeConfig[name]===v?'selected':''}>${v}</option>`).join('')}</select></div>`).join('')}</div><div id="shape-diagram" aria-live="polite">${error?`<p class="error" role="alert">${e(error)}</p>`:`<div class="model-path">${[['Input IDs',r.input,'Integer addresses, not scores','token'],['Token + position embeddings',r.embedding,`${r.tokenParameters.toLocaleString()} token-table numbers + ${r.positionParameters.toLocaleString()} position numbers`,'vector'],[`${shapeConfig.layers} transformer blocks`,r.embedding,'Normalize → attention → residual add → normalize → feed-forward → residual add','weight'],['Final normalization + vocabulary projection',r.output,`${r.outputParameters.toLocaleString()} separate output weights; one score per vocabulary entry`,'result']].map(([name,shape,detail,kind],i)=>`<div class="model-node ${kind}"><span class="stage-number">0${i+1}</span><div><h3>${name}</h3><p>${detail}</p></div><code>[${shape.join(', ')}]</code></div>${i<3?'<div class="model-arrow" aria-hidden="true">↓</div>':''}`).join('')}</div><details><summary>Inside one attention head</summary><p>Queries, keys, values: <code>[${r.attention.join(', ')}]</code> — batch, heads, positions, head width.</p><p>Attention scores: <code>[${r.scores.join(', ')}]</code>. Each head has ${r.headWidth} coordinates. Outputs combine to <code>[${r.embedding.join(', ')}]</code>.</p><p>The shown parameter counts exclude biases and transformer-block parameters; they are not total model size.</p></details>`}</div></section>`;}
function runData(){return selectedRun.startsWith('import-')?state.runs[+selectedRun.slice(7)]:course.runs[selectedRun];}
function number(v,d=6){return typeof v==='number'&&Number.isFinite(v)?v.toFixed(d):'Unknown';}
function results(){const r=runData();return heading('Read the result, then the limits.','Measurements are useful when you know what produced them. These records are snapshots of local Python runs.','TRAINING & EVALUATION')+`<div class="results-toolbar"><div><label for="run-select">Recorded experiment</label><select id="run-select"><option value="none" ${selectedRun==='none'?'selected':''}>No data selected</option>${Object.keys(course.runs).map(id=>`<option value="${id}" ${selectedRun===id?'selected':''}>${id==='byte-training'?'Supplied byte run · 200 updates':'Supplied BPE check · 4 updates'}</option>`).join('')}${state.runs.map((r,i)=>`<option value="import-${i}" ${selectedRun==='import-'+i?'selected':''}>${e(r.name)} · ${r.metrics.at(-1).step} recorded updates</option>`).join('')}</select></div><div><label for="run-files">Import your recorded run</label><input type="file" id="run-files" multiple accept=".json,.jsonl,.txt"></div></div><p class="small muted">Choose manifest.json and metrics.jsonl together. Add result.json and sample.txt when available. Files stay in this browser; no Python process is started.</p><p id="import-status" role="status" aria-live="polite">${e(importMessage)}</p>${r?resultsDetail(r):'<section class="panel empty"><h2>No measurements yet</h2><p>Select a supplied record or import files. Missing data is unknown, never zero.</p><a class="button" href="#/labs">See local lab commands</a></section>'}`;}
function resultsDetail(r){const m=r.manifest,first=r.metrics[0],last=r.metrics.at(-1),best=r.metrics.reduce((a,b)=>a.validation_loss<b.validation_loss?a:b),isByte=m.tokenizer.merges.length===0,status=r.result?.status??'unknown — result.json missing';return `<div class="row between run-banner"><span class="tag recorded">Recorded run · ${e(status)}</span><span class="small muted">${isByte?'Byte':'Teaching BPE'} · ${m.config.vocab_size} vocabulary entries · ${e(m.device||'device unknown')}</span></div>${status==='failed'?`<div class="error" role="status"><strong>Training failed.</strong><pre class="failure-message">${e(r.result.error||'No error text was supplied.')}</pre></div>`:''}<div class="metric-summary"><div><span>Recorded optimizer updates</span><strong>${last.step}</strong><small>Requested final step: ${r.result?.requested_final_step??'unknown'}</small></div><div><span>Validation loss · nats / token</span><strong>${number(last.validation_loss,4)}</strong><small>Initial recorded value ${number(first.validation_loss,4)}</small></div><div><span>Measured loop time</span><strong>${number(last.elapsed_seconds,3)} <small>s</small></strong><small>Excludes encoding and model setup</small></div></div><section class="panel"><div class="row between"><h2>Learning curve</h2><span class="small chart-legend"><span class="train-key">━ Training</span><span class="val-key">┅ Validation</span></span></div>${chart(r.metrics)}<p class="small muted">Mean negative log probability, in nats per token. Same tokenizer and sampled-window protocol within this run.</p><details open><summary>Read exact measurements as a table</summary><div class="table-wrap" tabindex="0" role="region" aria-label="Recorded training measurements"><table><thead><tr><th scope="col">Optimizer updates</th><th scope="col">Train loss</th><th scope="col">Validation loss</th><th scope="col">Perplexity</th><th scope="col">Elapsed s</th></tr></thead><tbody>${r.metrics.map(x=>`<tr><th scope="row">${x.step}</th><td>${number(x.train_loss)}</td><td>${number(x.validation_loss)}</td><td>${x.validation_perplexity===null?'Not representable':number(x.validation_perplexity,4)}</td><td>${number(x.elapsed_seconds,3)}</td></tr>`).join('')}</tbody></table></div></details></section><div class="two-col"><section class="panel"><p class="eyebrow">SAMPLE FROM THE RECORD</p><h2>Better loss can still sound like this.</h2>${r.sample!==null?`<pre class="sample">${e(r.sample)}</pre>`:'<p class="empty">No sample supplied. Generation quality is unknown from this record.</p>'}<p class="small muted">A sample is evidence to inspect, not a general benchmark. These measurements do not establish chatbot competence or factual reliability.</p></section><section class="panel"><p class="eyebrow">CHECKPOINT CONTEXT</p><h2>Best and latest are different questions.</h2><dl class="facts"><dt>Best observed validation</dt><dd>Step ${best.step} · ${number(best.validation_loss,4)}</dd><dt>Latest recorded evaluation</dt><dd>Step ${last.step}</dd><dt>Reported final step</dt><dd>${r.result?.step??'Unknown'}</dd></dl><p class="small muted">These describe the record. Checkpoint files are not loaded or verified by this browser. Inspect your actual last.pt or best.pt locally.</p><a href="#/checkpoints">Follow the checkpoint journey →</a></section></div><div class="callout"><strong>${selectedRun==='byte-training'?'What this supplied run supports: ':selectedRun==='bpe-check'?'A mechanical BPE check: ':'Interpret within this run: '}</strong>${selectedRun==='byte-training'?'Validation loss improved on fixed sampled windows from synthetic story templates. The repetitive continuation shows why that is not broad language understanding.':selectedRun==='bpe-check'?'A four-update run with 320 vocabulary entries. It is not a 200-update byte experiment or a quality comparison.':'Inspect data, sampling, status, and the actual sample before making a capability claim.'} Never rank different tokenizers by raw loss or perplexity.</div><details class="panel"><summary>Run identity, configuration, and measurement protocol</summary><dl class="facts"><dt>Model</dt><dd>${m.config.layers} layers · width ${m.config.width} · ${m.config.heads} heads · context ${m.config.context}</dd><dt>Seed / batch / learning rate</dt><dd>${e(m.seed)} / ${e(m.batch_size)} / ${e(m.learning_rate)}</dd><dt>Parameters</dt><dd>${e(m.parameters?.toLocaleString()??'Unknown')}</dd><dt>Training / validation documents</dt><dd>${m.data.train.documents} / ${m.data.validation.documents}</dd><dt>Evaluation</dt><dd>${e(m.evaluation.method||'Fixed sampled windows')} · ${m.evaluation.batches} batches · seed ${m.evaluation.seed}</dd><dt>Tokenizer SHA-256</dt><dd><code>${e(m.tokenizer_sha256)}</code></dd><dt>Training data SHA-256</dt><dd><code>${e(m.data.train.sha256)}</code></dd><dt>Validation data SHA-256</dt><dd><code>${e(m.data.validation.sha256)}</code></dd><dt>Record freshness</dt><dd>A saved snapshot; process activity and file freshness are unknown.</dd></dl><p class="small muted">Import validates the tokenizer fingerprint and record structure; it cannot independently prove measurements or inspect original data files.</p></details>`;}
function chart(rows){const max=Math.max(1,...rows.flatMap(r=>[r.train_loss,r.validation_loss]))*1.1,last=Math.max(1,rows.at(-1).step),x=s=>60+620*s/last,y=l=>235-195*l/max;return `<svg class="loss-chart" viewBox="0 0 740 285" role="img" aria-labelledby="chart-title chart-description"><title id="chart-title">Recorded training and validation loss</title><desc id="chart-description">${rows.length} recorded evaluation points. Horizontal axis: optimizer updates. Vertical axis: mean negative log probability in nats per token. Exact values in the adjacent table.</desc>${[0,1,2,3,4].map(i=>{const v=max*i/4;return `<line x1="60" x2="680" y1="${y(v)}" y2="${y(v)}" class="gridline"/><text x="48" y="${y(v)+4}" text-anchor="end">${v.toFixed(1)}</text>`;}).join('')}${rows.filter((r,i)=>i===0||i===rows.length-1||i%Math.max(1,Math.ceil(rows.length/5))===0).map(r=>`<text x="${x(r.step)}" y="255" text-anchor="middle">${r.step}</text>`).join('')}<text x="370" y="279" text-anchor="middle">Optimizer updates</text><polyline class="train-line" points="${rows.map(r=>`${x(r.step)},${y(r.train_loss)}`).join(' ')}"/><polyline class="validation-line" points="${rows.map(r=>`${x(r.step)},${y(r.validation_loss)}`).join(' ')}"/>${rows.map(r=>`<circle class="val-point" cx="${x(r.step)}" cy="${y(r.validation_loss)}" r="4"/>`).join('')}</svg>`;}
function notebook(){return heading('Keep an experiment trail.','Write down the question before the result. Keep failed attempts and uncertainty alongside successes.','YOUR NOTEBOOK')+`<div class="callout"><strong data-storage>${saveOK&&!sessionMemory?'Saved locally':'Save unavailable · export a backup'}</strong>. Notes and progress belong to this browser and site address. They do not sync across devices. Export before changing browsers or clearing storage.</div><div class="row backup-actions"><button class="primary" data-action="export">Export progress & notes</button><button data-action="export-text">Export notes as text</button><label class="button" for="backup-file">Import backup</label><input id="backup-file" type="file" accept=".json"></div><p class="small muted">Import merges progress and appends differing notes; your current work is preserved. Evidence stays self-reported.</p><p id="backup-status" role="status" aria-live="polite"></p><section class="panel notebook-fields">${C.NOTE_FIELDS.map((name,i)=>`<div><label for="note-${i}"><span class="field-number">${String(i+1).padStart(2,'0')}</span>${e(name)}</label><textarea id="note-${i}" data-note="${e(name)}" maxlength="20000" rows="${i===6?4:3}" placeholder="${i===0?'What do you expect, and why?':i===2?'Keep the run directory and saved step together.':'Your observation…'}">${e(state.notes[name])}</textarea></div>`).join('')}</section>`;}
function capstone(){const reviewed=state.evidence.filter(x=>x.reviewed).length;return heading('Show the work. Explain its limits.','A weak model with reproducible evidence can meet the goal. An attractive sample alone cannot.','CAPSTONE · TWO OR THREE SITTINGS')+`<div class="callout"><strong>${reviewed} of 6 evidence entries self-reviewed.</strong> This records your judgment and artifact references. It does not inspect files, certify competence, or award automatic points.</div><div class="evidence-list">${C.EVIDENCE.map((name,i)=>`<section class="panel evidence-item"><div class="row between"><h2><span class="stage-number">${i+1}</span>${e(name)}</h2><span id="evidence-status-${i}" class="status-text">${state.evidence[i].reviewed?'Self-reviewed':state.evidence[i].note.trim()?'Evidence noted · review pending':'Unresolved'}</span></div><label for="evidence-${i}">Artifact reference and what it demonstrates</label><textarea id="evidence-${i}" data-evidence="${i}" maxlength="20000" rows="3" placeholder="Record the file or run folder, result, and anything still missing.">${e(state.evidence[i].note)}</textarea><label class="evidence-check"><input type="checkbox" data-reviewed="${i}" ${state.evidence[i].reviewed?'checked':''} ${!state.evidence[i].note.trim()?'disabled':''}> I reviewed this evidence against the deliverable</label></section>`).join('')}</div><section class="panel"><h2>The evidence rubric</h2><p class="muted">Assess actual artifacts. Give partial credit and name what is missing; there is no target loss or automatic graduation.</p><div class="table-wrap" tabindex="0" role="region" aria-label="Capstone rubric"><table><thead><tr><th scope="col">Evidence</th><th scope="col">Points</th><th scope="col">Full-credit behavior</th></tr></thead><tbody>${[['Representation','Exact round trips and correct tokenizer/model distinction'],['Data','Explicit splits, recorded identity, honest leakage limits'],['Training','Fresh initialization and a traceable bounded run'],['Evaluation','Comparable validation evidence and correctly scoped claims'],['Reuse and explanation','Saved-model generation, resume, and coherent explanation']].map(([a,b])=>`<tr><th scope="row">${a}</th><td>20</td><td>${b}</td></tr>`).join('')}</tbody></table></div><p>Finish: “This run demonstrates ____. It does not establish ____. The next experiment that would reduce my uncertainty is ____.”</p><div class="row"><button class="primary" data-action="export">Export evidence & notes</button><a href="#/lesson/12">Read the full capstone</a></div></section>`;}
function checkpoints(){return heading('Three actions. Different starting points.','Keep tokenizer, weights, and recorded step together. A tokenizer alone does not contain trained model weights.','CHECKPOINT JOURNEY')+`<section class="panel"><span class="tag">Local commands · no browser execution</span>${[['New training','Random weights','Yes, optimizer updates','python labs/lab.py train --train-data data/demo/train.jsonl --val-data data/demo/validation.jsonl --out runs/new-experiment --steps 200'],['Resume training','Checkpoint + saved optimizer state','Yes, additional updates','python labs/lab.py resume --checkpoint runs/first/last.pt --out runs/resumed --steps 100'],['Generate text','Checkpoint + saved tokenizer','No weight updates','python labs/lab.py generate --checkpoint runs/first/last.pt --prompt "Mira visited the " --temperature 0.8 --seed 17']].map(([name,start,update,command],i)=>`<section class="journey-step"><span class="stage-number">0${i+1}</span><div><h2>${name}</h2><p>${start} → <strong>${update}</strong>.</p>${C.markdown('```text\n'+command+'\n```','labs/WORKBOOK.md',{os:state.os})}</div></section>`).join('')}<div class="callout">Step 200 plus 100 additional updates targets step 300. After interruption, inspect last.pt; unsaved updates are not retained. Use a new output folder to preserve earlier attempts.</div><a href="#/lesson/09">Return to lesson 09 →</a></section>`;}
function labs(){return heading('Run the lab on your computer.','Check the command and working folder, then run it in your chosen Python environment.','FOUR LABS · ONE EXPERIMENT TRAIL')+`<div class="row backup-actions"><a class="button primary" href="course.zip" download>Download course & Python labs ↓</a><a class="button" href="#/lesson/${state.lastLesson||'00'}">Return to lesson ${state.lastLesson||'00'}</a><a href="#/checkpoints">Checkpoint journey →</a></div><div class="callout"><strong>No live training connection.</strong> Commands execute locally after you copy them to your terminal. Use fresh output directories. Existing directories are refused, not overwritten.</div><div class="row"><label for="lab-os">Command environment</label><select id="lab-os" data-os><option value="wsl" ${state.os==='wsl'?'selected':''}>WSL / Linux</option><option value="windows" ${state.os==='windows'?'selected':''}>Windows PowerShell</option></select></div><article class="prose lab-prose">${C.markdown(course.references['labs/WORKBOOK.md'],'labs/WORKBOOK.md',{omitTitle:true,os:state.os})}</article><a href="#/reference/${encodeURIComponent('reference/TROUBLESHOOTING.md')}">If a command fails: troubleshooting →</a>`;}
function glossary(){return heading('A word, in context.','Keep the vocabulary close while you work.','REFERENCE')+`<article class="panel prose">${C.markdown(course.references['reference/GLOSSARY.md'],'reference/GLOSSARY.md',{omitTitle:true})}</article><a href="#/lesson/${state.lastLesson||'00'}">Return to your lesson →</a>`;}
function reference(path){return course.references[path]?`<a class="quiet-link" href="#/lesson/${state.lastLesson||'00'}">← Back to learning</a><article class="panel prose">${C.markdown(course.references[path],path,{os:state.os})}</article>`:missing();}
function missing(){return heading('That page isn’t in this course.','Your progress is still here.')+'<a class="button primary" href="#/">Return to learning</a>';}
function render({focus=true}={}){const raw=location.hash.replace(/^#\/?/,'');const [path,query]=raw.split('?');route=path;const parts=path.split('/'),from=new URLSearchParams(query).get('from');let body;try{body=parts[0]==='lesson'?lesson(parts[1]):parts[0]==='roadmap'?roadmap():parts[0]==='explore'?explorer(parts[1],/^\d{2}$/.test(from)?from:null):parts[0]==='results'?results():parts[0]==='notebook'?notebook():parts[0]==='capstone'?capstone():parts[0]==='labs'?labs():parts[0]==='checkpoints'?checkpoints():parts[0]==='glossary'?glossary():parts[0]==='reference'?reference(decodeURIComponent(parts.slice(1).join('/'))):path===''?home():missing();}catch(ex){body=heading('This view could not be opened.','Your session has been retained.')+`<p role="alert">${e(ex.message)}</p><a href="#/">Return home</a>`;}
menu=false;document.body.classList.remove('menu-open');document.documentElement.dataset.theme=state.theme;$('#app').innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar"><a class="brand" href="#/"><b class="brand-mark" aria-hidden="true">f.</b><span><strong>LLM Foundations</strong><small>Build, measure, explain</small></span></a><nav aria-label="Workspace">${link('','Your learning space','⌂',path==='')}${link('explore/tokenizer','Interactive workshop','◇',parts[0]==='explore')}${link('results','Recorded results','↗',parts[0]==='results')}${link('notebook','Experiment notebook','▤',parts[0]==='notebook')}${link('capstone','Capstone evidence','✓',parts[0]==='capstone')}</nav><hr class="divider"><p class="outline-label">Course outline · 00–12</p><nav aria-label="Course lessons">${course.modules.map(m=>`<a class="nav-link lesson-link" href="#/lesson/${m.id}" ${parts[0]==='lesson'&&parts[1]===m.id?'aria-current="page"':''}><span class="lesson-num">${m.id}</span><span>${e(C.shortTitles[+m.id])}</span><span class="sr-only">Lesson ${m.id}, ${state.lessons[m.id]?.read?'read':'not marked read'}</span></a>`).join('')}</nav><hr class="divider"><nav aria-label="Resources">${link('labs','Python labs','›',parts[0]==='labs')}${link('glossary','Glossary','Aa',parts[0]==='glossary')}</nav></aside><div class="workspace"><header class="topbar"><div class="row"><button class="mobile-toggle" data-action="menu" aria-controls="sidebar" aria-expanded="false">☰ <span class="sr-only">Course navigation</span></button><p class="desktop-label">YOUR WORKSHOP</p></div><div class="top-actions"><span class="meta desktop-label" data-storage>${saveOK&&!sessionMemory?'Saved locally':'Save unavailable · export a backup'}</span><button data-action="theme" aria-label="Switch to ${state.theme==='dark'?'light':'dark'} theme">${state.theme==='dark'?'☼ Light':'◐ Dark'}</button><a class="quiet-link" href="#/glossary">Glossary</a></div></header><main id="main" tabindex="-1" class="main">${storeError?`<div class="error" role="alert">${e(storeError)} <a href="#/notebook">Export your work</a></div>`:''}${body}<footer><span>LLM Foundations · Edition 2026.09</span><span>Local progress. Thoughtful evidence. <a href="#/reference/${encodeURIComponent('reference/SOURCES.md')}">Course sources</a></span></footer></main></div></div>`;
document.title=(parts[0]==='lesson'?`Lesson ${parts[1]} · `:parts[0]?parts[0][0].toUpperCase()+parts[0].slice(1)+' · ':'')+'LLM Foundations';if(focus){$('#main').focus({preventScroll:true});window.scrollTo(0,0);}bindForms();}
function updateExplorer(){const active=document.activeElement?.id;$('#explorer-panel').innerHTML=tool==='tokenizer'?tokenizerView():tool==='shapes'?shapesView():predictionView(tool==='attention');if(active)document.getElementById(active)?.focus({preventScroll:true});}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Exported. Keep the downloaded file as your backup.');}
async function importBackup(file){if(!file)return;if(file.size>25_000_000)throw Error('Backup is too large. Maximum size is 25 MB.');const value=C.validateState(JSON.parse(await file.text()));for(const r of value.runs)await C.verifyRunIdentity(r);state=C.mergeState(state,value);persist();render({focus:false});$('#backup-status').textContent='Backup imported and merged. Existing notes were preserved.';}
function bindForms(){const form=$('#quiz-form');if(form)form.addEventListener('submit',ev=>{ev.preventDefault();const id=form.dataset.lesson,selection=Number(new FormData(form).get('answer')),correct=selection===questions[+id][2];feedback[id]={selection,correct};C.setProgress(state,id,'practiced',true);if(correct)C.setProgress(state,id,'checked',true);persist();$('#quiz-feedback').innerHTML=`<strong>${correct?'That’s right.':'Try the idea again.'}</strong> ${e(questions[+id][3])}`;$('[data-progress="practiced"]').checked=true;$('[data-check-state]').textContent=state.lessons[id].checked?'answered correctly':'not yet checked';});}
document.addEventListener('click',async ev=>{const copy=ev.target.closest('[data-copy]');if(copy){try{await navigator.clipboard.writeText(copy.dataset.copy);toast('Copied. Run it locally from the course folder.');}catch{toast('Clipboard unavailable. Select and copy the command text.');}return;}const pos=ev.target.closest('[data-position]');if(pos){position=+pos.dataset.position;stepped=true;updateExplorer();$(`[data-position="${position}"]`)?.focus({preventScroll:true});return;}const el=ev.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;
if(action==='theme'){state.theme=state.theme==='light'?'dark':'light';document.documentElement.dataset.theme=state.theme;el.textContent=state.theme==='dark'?'☼ Light':'◐ Dark';el.setAttribute('aria-label',`Switch to ${state.theme==='dark'?'light':'dark'} theme`);persist();}if(action==='menu'){menu=!menu;$('#sidebar').classList.toggle('open',menu);document.body.classList.toggle('menu-open',menu);el.setAttribute('aria-expanded',String(menu));if(menu)$('#sidebar a').focus();}if(action==='scroll-section'){const target=document.getElementById(el.dataset.target);target?.scrollIntoView({behavior:'auto',block:'start'});if(target){target.tabIndex=-1;target.focus({preventScroll:true});}}
if(action==='step'||action==='step-back'||action==='reset-simulation'){position=action==='reset-simulation'?0:Math.max(0,Math.min(3,position+(action==='step'?1:-1)));stepped=action!=='reset-simulation';if(action==='reset-simulation')futureToken=9;updateExplorer();const next=$(`[data-action="${action}"]`);if(next&&!next.disabled)next.focus({preventScroll:true});else $(`[data-position="${position}"]`).focus({preventScroll:true});}if(action==='save-quick'){const note=$('#lesson-note').value.trim();if(!note)return toast('Write an observation first.');const key='Observed losses, sample behavior, and elapsed time';const combined=[state.notes[key],`Lesson ${el.dataset.id}: ${note}`].filter(Boolean).join('\n\n');if(combined.length>20000)return toast('This field is full. Export your notes before adding more.');state.notes[key]=combined;persist();$('#lesson-note').value='';toast(saveOK?'Observation saved to your notebook.':'Kept for this session. Export a backup.');}if(action==='export')download(JSON.stringify(state,null,2),'llm-foundations-backup.json','application/json');if(action==='export-text')download(C.NOTE_FIELDS.map(f=>`${f}:\n${state.notes[f]||'(not recorded)'}`).join('\n\n')+'\n\nCAPSTONE EVIDENCE (SELF-REPORTED)\n'+C.EVIDENCE.map((x,i)=>`${x}\n${state.evidence[i].reviewed?'Self-reviewed':'Unresolved / review pending'}\n${state.evidence[i].note||'(not recorded)'}`).join('\n\n'),'llm-foundations-notes.txt','text/plain');});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&menu){menu=false;$('#sidebar').classList.remove('open');document.body.classList.remove('menu-open');const b=$('[data-action="menu"]');b.setAttribute('aria-expanded','false');b.focus();}});
document.addEventListener('input',ev=>{const el=ev.target;if(el.dataset.note){state.notes[el.dataset.note]=el.value;persist();}if(el.dataset.evidence!==undefined){const i=+el.dataset.evidence;state.evidence[i].note=el.value;if(!el.value.trim())state.evidence[i].reviewed=false;const c=$(`[data-reviewed="${i}"]`);c.disabled=!el.value.trim();c.checked=state.evidence[i].reviewed;$(`#evidence-status-${i}`).textContent=state.evidence[i].reviewed?'Self-reviewed':el.value.trim()?'Evidence noted · review pending':'Unresolved';persist();}if(el.id==='token-text'){tokenText=el.value;$('#token-result').innerHTML=tokenizerResult();}if(el.id==='future-token'){if(!/^\d+$/.test(el.value)||+el.value>999){el.setCustomValidity('Enter a whole token ID from 0 to 999.');return;}el.setCustomValidity('');futureToken=+el.value;}});
document.addEventListener('change',async ev=>{const el=ev.target;try{if(el.matches('[data-os]')){state.os=el.value;persist();render({focus:false});document.querySelector('[data-os]')?.focus();}if(el.dataset.progress){C.setProgress(state,el.dataset.id,el.dataset.progress,el.checked);persist();toast('Progress updated. Capstone evidence is unchanged.');}if(el.dataset.reviewed!==undefined){const i=+el.dataset.reviewed;if(!state.evidence[i].note.trim())return;state.evidence[i].reviewed=el.checked;persist();render({focus:false});$(`[data-reviewed="${i}"]`).focus({preventScroll:true});}if(el.id==='tokenizer-mode'){tokenMode=el.value;$('#token-result').innerHTML=tokenizerResult();}if(el.id==='token-example'&&el.value!==''){tokenText=course.cases[+el.value].text;$('#token-text').value=tokenText;$('#token-result').innerHTML=tokenizerResult();}if(el.dataset.shape){shapeConfig[el.dataset.shape]=+el.value;updateExplorer();}if(el.id==='future-token'&&el.checkValidity())updateExplorer();if(el.id==='run-select'){selectedRun=el.value;importMessage='';render({focus:false});$('#run-select').focus();}
if(el.id==='run-files'){if(!el.files.length)return;$('#import-status').textContent='Importing and validating recorded files…';if(state.runs.length>=20)throw Error('Maximum 20 imported runs. Export your work before starting another notebook.');if(el.files.length>4||[...el.files].reduce((n,f)=>n+f.size,0)>1_000_000)throw Error('Select up to four recorded files, under 1 MB combined.');const names=[...el.files].map(f=>f.name);if(new Set(names).size!==names.length||names.some(n=>!['manifest.json','metrics.jsonl','result.json','sample.txt'].includes(n)))throw Error('Use manifest.json, metrics.jsonl, result.json, and sample.txt.');const files=await Promise.all([...el.files].map(async f=>({name:f.name,text:await f.text()})));const run=C.parseRunFiles(files);await C.verifyRunIdentity(run);state.runs.push(run);selectedRun='import-'+(state.runs.length-1);persist();importMessage='Valid recorded data imported. This does not indicate a running process.';render({focus:false});}if(el.id==='backup-file')await importBackup(el.files[0]);}catch(ex){const msg='Import error: '+(ex instanceof SyntaxError?'The backup is not valid JSON.':ex.message);const target=el.id==='backup-file'?$('#backup-status'):$('#import-status');if(target)target.textContent=msg;toast(msg);}});
function webmcp(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();for(const tool of [{name:'get_learning_progress',title:'Read learning progress',description:'Read local reading, practice, and knowledge-check progress. Evidence remains self-reported.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:input=>{if(!input||Object.keys(input).length)throw Error('Expected an empty object');return {lastLesson:state.lastLesson,lessons:state.lessons,evidenceReviewed:state.evidence.filter(e=>e.reviewed).length};}},{name:'open_course_lesson',title:'Open a lesson',description:'Navigate to a lesson and record reading status. Does not mark it read, practiced, checked, or award evidence.',inputSchema:{type:'object',properties:{lessonId:{type:'string',pattern:'^(0[0-9]|1[0-2])$'}},required:['lessonId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||Object.keys(input).length!==1||!course.modules.some(m=>m.id===input.lessonId))throw Error('Unknown lesson ID');history.replaceState(null,'','#/lesson/'+input.lessonId);render();return {lessonId:input.lessonId,status:'reading'};}}])try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
async function init(){try{const response=await fetch('content.json');if(!response.ok)throw Error('Course content is unavailable.');course=await response.json();if(course.modules?.length!==13)throw Error('Course curriculum is incomplete.');for(const r of Object.values(course.runs))C.validateRun(r);render({focus:false});window.addEventListener('hashchange',()=>render());webmcp();}catch(ex){$('#app').innerHTML=`<main class="loading"><h1>The course could not be opened.</h1><p role="alert">${e(ex.message)}</p><p>Saved notes have not changed. Reload when course files are available, or <a href="course.zip">download the supplied course</a>.</p><button onclick="location.reload()">Try again</button></main>`;}}
init();
